import java.io.IOException;
import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserFactory;
import org.apache.abdera.parser.ParserOptions;

/**
 * Secure implementation of an Atom provider.
 *
 * The original version created (or reused) a {@link Parser} instance and
 * changed its {@link ParserOptions} inside a synchronized block.  Because the
 * same {@link Parser} could be reused by other threads, the security options
 * were not reliably applied before parsing, leaving the application vulnerable
 * to XML External Entity (XXE) attacks.
 *
 * This patched version creates a brand‑new {@link Parser} for each request,
 * configures the {@link ParserOptions} **before** the parser is used and
 * disables entity resolution completely.  No synchronization is required,
 * eliminating the race condition that previously existed.
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // -----------------------------------------------------------------------
    // Secure readFrom implementation
    // -----------------------------------------------------------------------
    @Override
    public T readFrom(Class<T> clazz,
                      Type genericType,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // -------------------------------------------------------------------
        // 1. Build a fresh, immutable ParserOptions instance with all unsafe
        //    features disabled.
        // -------------------------------------------------------------------
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Disable resolution of external entities (prevents XXE)
        options.setResolveEntities(false);
        // Some Abdera versions also expose an explicit flag for expanding
        // entity references; ensure it is turned off as well.
        options.setExpandEntityReferences(false);

        // -------------------------------------------------------------------
        // 2. Obtain a brand‑new Parser that is bound to the hardened options.
        //    Using a fresh parser guarantees that no other thread can reuse a
        //    parser that was previously configured with unsafe defaults.
        // -------------------------------------------------------------------
        ParserFactory factory = ATOM_ENGINE.getParserFactory();
        Parser parser = factory.newParser(options);

        // -------------------------------------------------------------------
        // 3. Parse the incoming XML safely.
        // -------------------------------------------------------------------
        Document<T> doc = parser.parse(entityStream);
        return doc.getRoot();
    }

    // other methods (writeTo, etc.) remain unchanged
}
