private static void decompress(InputStream in, byte[] out) throws IOException {
    int position = 0;
    final int total = out.length;
    while (position < total) {
        int n = in.read();
        if (n == -1) {
            throw new IOException("Unexpected end of compressed data");
        }
        if (n > 128) {
            int repeatCount = n & 0x7F;
            if (repeatCount == 0) {
                throw new IOException("Invalid repeat count 0");
            }
            int value = in.read();
            if (value == -1) {
                throw new IOException("Unexpected end of compressed data while reading repeat value");
            }
            if (position + repeatCount > total) {
                throw new IOException("Decompressed data exceeds expected size");
            }
            for (int i = 0; i < repeatCount; i++) {
                out[position++] = (byte) value;
            }
        } else {
            int literalCount = n;
            if (literalCount == 0) {
                throw new IOException("Invalid literal count 0");
            }
            if (position + literalCount > total) {
                throw new IOException("Decompressed data exceeds expected size");
            }
            for (int i = 0; i < literalCount; i++) {
                int b = in.read();
                if (b == -1) {
                    throw new IOException("Unexpected end of compressed data while reading literals");
                }
                out[position++] = (byte) b;
            }
        }
