     * @return a validated {@link Locale} or {@code null} if the input is invalid
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        if (requestedLocale == null) {
            return null;
        }

        Locale locale = null;

        if (requestedLocale instanceof Locale) {
            Locale candidate = (Locale) requestedLocale;
            if (isValidLocale(candidate)) {
                locale = candidate;
            }
        } else if (requestedLocale instanceof String) {
            String candidate = ((String) requestedLocale).trim();
            if (isValidLocaleString(candidate)) {
                locale = LocalizedTextUtil.localeFromString(candidate, null);
            }
        } else {
            // Fallback for unexpected object types – treat the object's string
            // representation as a candidate only after validation.
            String candidate = requestedLocale.toString().trim();
            if (isValidLocaleString(candidate)) {
                locale = LocalizedTextUtil.localeFromString(candidate, null);
            }
        }

        if (locale != null) {
            LOG.debug("Applied request locale: {}", locale);
        } else {
            LOG.debug("Invalid locale parameter supplied: {}", requestedLocale);
        }

        return locale;
    }

    /**
     * Validates a locale string against the whitelist pattern.
     *
     * @param localeStr the locale string to validate
     * @return {@code true} if the string matches the allowed pattern
     */
    private static boolean isValidLocaleString(String localeStr) {
        return localeStr != null && LOCALE_PATTERN.matcher(localeStr).matches();
    }

    /**
