private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
    Path targetDirPath = targetDirectory.toPath().toRealPath(LinkOption.NOFOLLOW_LINKS);
    ArchiveEntry entry = supplier.getNextReadableEntry();
    while (entry != null) {
        String entryName = entry.getName();
        if (entryName == null) {
            throw new IOException("Archive entry name is null");
        }
        // reject absolute paths
        if (new File(entryName).isAbsolute()) {
            throw new IOException("Entry name '" + entryName + "' is absolute");
        }
        // resolve against target dir and normalize
        Path entryPath = targetDirPath.resolve(entryName).normalize();

        // ensure entryPath is still within targetDirPath
        if (!entryPath.startsWith(targetDirPath)) {
            throw new IOException("Entry '" + entryName + "' would be extracted outside of target directory");
        }

        if (entry.isDirectory()) {
            Files.createDirectories(entryPath);
        } else {
            Path parent = entryPath.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            try (OutputStream out = Files.newOutputStream(entryPath, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING)) {
                writer.writeEntryDataTo(entry, out);
            }
        }
        entry = supplier.getNextReadableEntry();
    }
}
