import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.apache.commons.compress.archivers.ArchiveEntry;

/**
 * Utility that expands archive entries into a target directory while protecting
 * against path‑traversal attacks.
 */
public class Expander {

    // other methods ...

    /**
     * Expands entries supplied by {@code supplier} into {@code targetDirectory}.
     * <p>
     * The implementation normalises each entry path and verifies that the
     * resulting location is a descendant of {@code targetDirectory}.  Absolute
     * entry names and any attempt to escape the target directory (e.g. using
     * “../”) cause an {@link IOException} to be thrown.
     *
     * @param supplier        supplies the next readable {@link ArchiveEntry}
     * @param writer          writes the entry data to an {@link OutputStream}
     * @param targetDirectory directory into which entries are extracted
     * @throws IOException if an I/O error occurs or a security check fails
     */
    private void expand(ArchiveEntrySupplier supplier,
                         EntryWriter writer,
                         File targetDirectory) throws IOException {

        // Resolve the target directory to its real (canonical) path once.
        // NOFOLLOW_LINKS prevents a symlinked target directory from being
        // used to escape the intended location.
        final Path targetDirPath = targetDirectory.toPath()
                                                   .toRealPath(LinkOption.NOFOLLOW_LINKS);

        ArchiveEntry entry = supplier.getNextReadableEntry();
        while (entry != null) {
            final String entryName = entry.getName();

            if (entryName == null) {
                throw new IOException("Archive entry name is null");
            }

            // Reject absolute paths – they would ignore the target directory.
            if (new File(entryName).isAbsolute()) {
                throw new IOException("Entry name '" + entryName + "' is absolute");
            }

            // Resolve the entry against the target directory and normalise it.
            // Normalisation removes “.” and “..” components.
            final Path entryPath = targetDirPath.resolve(entryName).normalize();

            // Ensure the normalised path is still inside the target directory.
            if (!entryPath.startsWith(targetDirPath)) {
                throw new IOException(
                    "Entry '" + entryName + "' would be extracted outside of target directory");
            }

            // Disallow extraction to an existing symbolic link (could be used
            // to redirect writes elsewhere).  The check is performed after the
            // path has been resolved but before any file is created.
            if (Files.isSymbolicLink(entryPath)) {
                throw new IOException(
                    "Entry '" + entryName + "' resolves to a symbolic link, which is not allowed");
            }

            if (entry.isDirectory()) {
                // Create the directory (including any missing parents).
                Files.createDirectories(entryPath);
            } else {
                // Ensure parent directories exist.
                final Path parent = entryPath.getParent();
                if (parent != null) {
                    Files.createDirectories(parent);
                }

                // Write the entry data atomically.
                try (OutputStream out = Files.newOutputStream(
                        entryPath,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(entry, out);
                }
            }

            entry = supplier.getNextReadableEntry();
        }
    }

    // other methods ...

