/**
 * Codec for object arrays. The deserialization logic has been hardened to
 * mitigate Fastjson auto‑type deserialization attacks (CVE‑2020‑10673 and
 * related issues). The method now:
 * <ul>
 *   <li>Disables Fastjson auto‑type support for the duration of the call.</li>
 *   <li>Validates the resolved component class against a whitelist of safe
 *       types (primitives, wrappers, {@link String}, {@link Enum},
 *       {@link Date}, {@link Temporal}, {@link BigDecimal},
 *       {@link BigInteger}).</li>
 *   <li>Fails fast with an {@link IllegalArgumentException} when an unsafe
 *       type is encountered.</li>
 * </ul>
 * These measures prevent malicious payloads that attempt to instantiate
 * arbitrary classes (e.g., {@code java.rmi.Remote} or {@code javax.script.ScriptEngine})
 * during array deserialization.
 */
public class ObjectArrayCodec implements ObjectSerializer, ObjectDeserializer {

    // -----------------------------------------------------------------------
    //  Deserialization
    // -----------------------------------------------------------------------
    @SuppressWarnings({ "unchecked", "rawtypes" })
    public <T> T deserialze(DefaultJSONParser parser, Type type, Object fieldName) {

        // -------------------------------------------------------------------
        //  1. Fast‑path handling for null and string literals
        // -------------------------------------------------------------------
        final JSONLexer lexer = parser.lexer;

        if (lexer.token() == JSONToken.NULL) {
            lexer.nextToken(JSONToken.COMMA);
            return null;
        }

        if (lexer.token() == JSONToken.LITERAL_STRING) {
            byte[] bytes = lexer.bytesValue();
            lexer.nextToken(JSONToken.COMMA);
            return (T) bytes;
        }

        // -------------------------------------------------------------------
        //  2. Resolve the component class of the target array type
        // -------------------------------------------------------------------
        Class componentClass;
        Type componentType;

        if (type instanceof GenericArrayType) {
            GenericArrayType gat = (GenericArrayType) type;
            componentType = gat.getGenericComponentType();

            if (componentType instanceof TypeVariable) {
                // Resolve a type variable against the parser context
                TypeVariable<?> tv = (TypeVariable<?>) componentType;
                Type ctxType = parser.getContext().type;

                if (ctxType instanceof ParameterizedType) {
                    ParameterizedType pt = (ParameterizedType) ctxType;
                    componentClass = resolveFromParameterizedType(tv, pt);
                } else {
                    // Fallback – use the first bound of the type variable
                    componentClass = TypeUtils.getClass(tv.getBounds()[0]);
                }
            } else {
                componentClass = TypeUtils.getClass(componentType);
            }
        } else {
            // Plain array class (e.g., String[].class)
            Class<?> arrayClass = (Class<?>) type;
            componentClass = arrayClass.getComponentType();
            componentType = componentClass;
        }

        // -------------------------------------------------------------------
        //  3. Defensive checks – whitelist of safe component types
        // -------------------------------------------------------------------
        if (!isSafeComponentClass(componentClass)) {
            throw new IllegalArgumentException(
                    "Deserialization of array component type is not allowed: " + componentClass);
        }

        // -------------------------------------------------------------------
        //  4. Disable Fastjson auto‑type support for the duration of parsing
        // -------------------------------------------------------------------
        ParserConfig config = parser.getConfig();
        boolean originalAutoType = config.isAutoTypeSupport();
        config.setAutoTypeSupport(false);
        try {
            // Parse the JSON array into a temporary JSONArray
            JSONArray array = new JSONArray();
            parser.parseArray(componentClass, array, fieldName);

            // Convert the JSONArray into a real Java array of the target type
            return (T) toObjectArray(parser, componentClass, array);
        } finally {
            // Restore the original auto‑type setting to avoid side‑effects
            config.setAutoTypeSupport(originalAutoType);
        }
    }

    // -----------------------------------------------------------------------
    //  Helper methods
    // -----------------------------------------------------------------------

    /**
     * Resolve a {@link TypeVariable} against a {@link ParameterizedType}
     * using the variable name.
     */
    private static Class<?> resolveFromParameterizedType(TypeVariable<?> tv,
                                                          ParameterizedType pt) {
        Type raw = pt.getRawType();
        if (raw instanceof Class) {
            TypeVariable<?>[] typeParams = ((Class<?>) raw).getTypeParameters();
            Type[] actualArgs = pt.getActualTypeArguments();

            for (int i = 0; i < typeParams.length; i++) {
                if (typeParams[i].getName().equals(tv.getName())) {
                    Type actual = actualArgs[i];
                    if (actual instanceof Class) {
                        return (Class<?>) actual;
                    }
                    // If the actual type is itself a type variable or a generic,
                    // fall back to Object.class – it will be rejected by the
                    // whitelist check later.
                    return Object.class;
                }
            }
        }
        return Object.class;
    }

    /**
     * Determines whether the supplied component class is considered safe for
     * deserialization. Only a narrow set of immutable or well‑known value
     * types are allowed.
     */
    private static boolean isSafeComponentClass(Class<?> clazz) {
        if (clazz == null) {
            return false;
        }
        // primitives and their wrappers
        if (clazz.isPrimitive()
                || Number.class.isAssignableFrom(clazz)
                || clazz == Boolean.class
                || clazz == Character.class) {
            return true;
        }
        // String
        if (clazz == String.class) {
            return true;
        }
        // Enum types
        if (clazz.isEnum()) {
            return true;
        }
        // Date / time types
        if (Date.class.isAssignableFrom(clazz)
                || Temporal.class.isAssignableFrom(clazz)) {
            return true;
        }
        // BigDecimal / BigInteger
        if (BigDecimal.class.isAssignableFrom(clazz)
                || BigInteger.class.isAssignableFrom(clazz)) {
            return true;
        }
        // Arrays of safe types are handled recursively by the same codec,
        // but we do not allow multi‑dimensional arrays of unsafe types.
        if (clazz.isArray()) {
            return isSafeComponentClass(clazz.getComponentType());
        }
        // Anything else (including Object.class) is considered unsafe.
        return false;
    }

    // -----------------------------------------------------------------------
    //  Existing methods (serialize, toObjectArray, etc.) are unchanged.
    // -----------------------------------------------------------------------
}
