@Converter
public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
    if (source == null) {
        throw new IllegalArgumentException("source must not be null");
    }

    InputSource inputSource;
    try {
        if (source.getReader() != null) {
            inputSource = new InputSource(source.getReader());
        } else if (source.getInputStream() != null) {
            inputSource = new InputSource(source.getInputStream());
        } else {
            throw new IllegalArgumentException("StreamSource must provide either a Reader or InputStream");
        }
    } catch (Exception e) {
        throw new SAXException("Failed to create InputSource", e);
    }
    inputSource.setSystemId(source.getSystemId());
    inputSource.setPublicId(source.getPublicId());

    SAXParserFactory factory = null;
    if (exchange != null) {
        factory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
    }
    if (factory == null) {
        factory = SAXParserFactory.newInstance();
    }

    // configure factory securely
    factory.setNamespaceAware(true);
    try {
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
    } catch (ParserConfigurationException | SAXNotRecognizedException | SAXNotSupportedException e) {
        LOG.warn("Unable to set FEATURE_SECURE_PROCESSING: {}", e.getMessage());
    }
    try {
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
    } catch (ParserConfigurationException | SAXNotRecognizedException | SAXNotSupportedException e) {
        LOG.warn("Unable to disable external entities on SAXParserFactory: {}", e.getMessage());
    }

    XMLReader xmlReader;
    try {
        SAXParser parser = factory.newSAXParser();
        xmlReader = parser.getXMLReader();

        // additional hardening on the XMLReader
        try {
            xmlReader.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        } catch (SAXNotRecognizedException | SAXNotSupportedException e) {
            LOG.warn("Unable to disallow DOCTYPE declarations: {}", e.getMessage());
        }
        try {
            xmlReader.setFeature("http://xml.org/sax/features/external-general-entities", false);
            xmlReader.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        } catch (SAXNotRecognizedException | SAXNotSupportedException e) {
            LOG.warn("Unable to disable external entities on XMLReader: {}", e.getMessage());
        }
    } catch (ParserConfigurationException | SAXException e) {
        LOG.warn("Failed to create secure XMLReader: {}", e.getMessage());
        throw new SAXException("Unable to create a secure XMLReader", e);
    }

    return new SAXSource(xmlReader, inputSource);
}
