        // disable external entities explicitly.
    }

    // Disallow the parser from resolving external entities
    try {
        factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, Boolean.FALSE);
    } catch (IllegalArgumentException e) {
        // ignore if not supported
    }

    // Keep useful, safe features
    factory.setProperty(XMLInputFactory.IS_COALESCING, Boolean.TRUE);
    // Entity references are replaced only for internal entities; external ones are already disabled
    factory.setProperty(XMLInputFactory.IS_REPLACING_ENTITY_REFERENCES, Boolean.TRUE);

    // Create the reader on a stream that strips any leading XML declaration prefixes
    return factory.createXMLStreamReader(wrapPrefixRemovingInputStream(inputStream));
