import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.security.Principal;
import java.util.Objects;

/**
 * Checks whether a self‑update request for a {@link ScimUser} is allowed.
 *
 * <p>The original implementation only compared the email address in the request
 * with the one stored in the database.  That allowed an attacker to change the
 * email of any user by simply supplying a different email value.  The patched
 * version adds strict authorization checks:
 *
 * <ul>
 *   <li>Extracts the authenticated user identifier from {@link HttpServletRequest#getUserPrincipal()}
 *       (or {@code request.getRemoteUser()}) and ensures it matches the user ID
 *       extracted from the request URL.</li>
 *   <li>Allows the operation to proceed only if the caller is the owner of the
 *       account or possesses an administrative role (e.g. {@code "admin"} or
 *       {@code "uaa.admin"}).</li>
 *   <li>Handles malformed JSON, missing request bodies and {@code null} values
 *       safely using {@link Objects#equals}.</li>
 *   <li>Preserves the original field‑by‑field immutability checks for
 *       {@code primaryEmail}, {@code userName}, {@code verified},
 *       {@code active} and {@code origin}.</li>
 * </ul>
 *
 * This makes the method safe for production use under Java 8.
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }

    /**
     * Determines whether the incoming request is allowed to update the user.
     *
     * @param request the HTTP request containing the JSON payload and authentication information
     * @return {@code true} if the update is permitted, {@code false} otherwise
     * @throws IOException if the request body cannot be read
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // -----------------------------------------------------------------
        // 1.  Authorisation – the caller must be the owner of the account or an admin.
        // -----------------------------------------------------------------
        String authenticatedUserId = extractAuthenticatedUserId(request);
        if (authenticatedUserId == null) {
            // No authenticated principal – deny the request.
            return false;
        }

        // User ID that the request is trying to modify (extracted from the URL).
        String targetUserId = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // Allow if the caller is the owner or has an admin role.
        boolean isOwner = Objects.equals(authenticatedUserId, targetUserId);
        boolean isAdmin = request.isUserInRole("admin") || request.isUserInRole("uaa.admin");
        if (!isOwner && !isAdmin) {
            return false;
        }

        // -----------------------------------------------------------------
        // 2.  Parse request payload.
        // -----------------------------------------------------------------
        String requestBody = IOUtils.toString(request.getReader());
        if (requestBody == null || requestBody.trim().isEmpty()) {
            // Empty payload – nothing to validate, reject.
            return false;
        }

        ScimUser scimUserFromRequest;
        try {
            scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);
        } catch (Exception e) {
            // Malformed JSON – reject the request.
            return false;
        }

        // -----------------------------------------------------------------
        // 3.  Retrieve the persisted user record.
        // -----------------------------------------------------------------
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(targetUserId, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist we cannot safely allow an update.
            return false;
        }

        // -----------------------------------------------------------------
        // 4.  Field‑by‑field immutability checks.
        // -----------------------------------------------------------------
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the update is allowed.
        return true;
    }

    /**
     * Extracts the authenticated user identifier from the request.
     *
     * <p>The method first checks {@link HttpServletRequest#getUserPrincipal()}.
     * If that is {@code null}, it falls back to {@link HttpServletRequest#getRemoteUser()}.
     * Implementations that store the user ID in a custom request attribute can
     * extend this method accordingly.
     *
     * @param request the incoming HTTP request
     * @return the authenticated user ID, or {@code null} if the request is unauthenticated
     */
    private String extractAuthenticatedUserId(HttpServletRequest request) {
        Principal principal = request.getUserPrincipal();
        if (principal != null) {
            return principal.getName();
        }
        // Fallback for containers that expose the remote user directly.
        return request.getRemoteUser();
    }

    // other methods …
}
